<script setup>
import {computed,ref,watch,nextTick} from 'vue'
import {groupJourneyEvents} from '../services/gantt-model.js'
const props=defineProps({surgery:Object,scenario:Object,viewDate:String}),emit=defineEmits(['close'])
const content=ref()
watch(()=>props.surgery?.id,async()=>{await nextTick();if(content.value)content.value.scrollTop=0})
const close=()=>emit('close')
const groups=computed(()=>groupJourneyEvents(props.scenario?.timelineEvents||[],props.surgery?.id,props.scenario?.meta.date,props.viewDate))
const time=value=>value?String(value).replace('T',' '):'—'
const deviation=v=>v==null?'—':v===0?'准时':v>0?`延误 ${v} 分钟`:`提前 ${Math.abs(v)} 分钟`
const sections=computed(()=>{const s=props.surgery||{};return [
{title:'患者与手术',fields:[['手术编号',s.surgeryNo],['手术名称',s.surgeryName],['科室 / 医疗组',[s.department,s.medicalGroupName].filter(Boolean).join(' / ')],['手术等级',s.surgeryLevel?`${s.surgeryLevel} 级`:null],['优先级',s.priority],['患者姓名',s.patientName],['患者 ID',s.patientId],['住院号',props.scenario?.patients?.find(p=>p.id===s.patientId)?.admissionNo],['性别 / 年龄',[s.patientGender,s.patientAge!=null?`${s.patientAge} 岁`:null].filter(Boolean).join(' / ')],['诊断',s.patientDiagnosis],['ASA 分级',s.asaGrade],['合并症',Array.isArray(s.comorbidities)?s.comorbidities.join('、'):s.comorbidities]]},
{title:'人员与资源',fields:[['主刀医生',s.surgeonName],['助手',s.assistantName],['麻醉医生',s.anesthesiologistName],['巡回护士',s.circulatingNurseName],['器械护士',s.scrubNurseName],['病房位置',s.locations?.ward?.path],['手术间',s.locations?.operatingRoom?.path||s.operatingRoomNo],['麻醉方式',s.anesthesiaType],['体位',s.position],['关键设备',(s.equipmentNames||[]).join('、')||'常规设备'],['计划复苏床位',s.recoveryBedNo||'待分配'],['特殊要求',s.specialRequirements||'无'],['备注',s.notes]]},
{title:'计划与实际',fields:[['计划开始',s.plannedStartTime],['计划结束',s.plannedEndTime],['实际开始',s.actualStartTime||'尚未开始'],['实际结束',s.actualEndTime||'尚未结束'],['开始偏差',s.actualStartTime?deviation(s.startDeviation):'—'],['结束偏差',s.actualEndTime?deviation(s.endDeviation):'—'],['计划时长',s.plannedDuration!=null?`${s.plannedDuration} 分钟`:null],['实际时长',s.actualDuration!=null?`${s.actualDuration} 分钟`:null]]},
{title:'患者全程',fields:[['入院',s.admissionTime],['转运入手术室',s.transferInTime],['计划复苏开始',s.plannedRecoveryStartTime],['计划复苏结束',s.plannedRecoveryEndTime],['实际复苏开始',s.recoveryStartTime],['实际复苏结束',s.recoveryEndTime||(s.recoveryStartTime?'复苏中':'未进入复苏')],['复苏进度截至',s.recoveryProgressEndTime],['复苏室',s.locations?.pacu?.path||s.pacuRoomNo],['转运出手术室',s.transferOutTime]]}]})
</script>
<template><aside class="journey-panel" aria-label="手术详情卡片"><div class="panel-heading"><div><h2>手术详情</h2><span class="caption muted">{{surgery?surgery.surgeryNo:'请选择手术'}}</span></div><VBtn icon="tabler-x" variant="text" color="secondary" size="small" aria-label="关闭手术详情" @click="close"/></div><div v-if="!surgery" class="journey-placeholder"><VIcon icon="tabler-file-pencil" size="34" color="secondary"/><h3>尚未选择手术</h3><p>点击甘特条带或搜索手术，同时查看详情与空间位置。</p></div><div v-else ref="content" class="journey-content"><div class="selection-summary"><strong>{{surgery.patientName}}</strong><span>{{surgery.surgeryName}}</span><div class="caption muted">{{surgery.operatingRoomNo}} · {{surgery.surgeryLevel}} 级 · {{surgery.status}}</div></div><VAlert v-if="viewDate!==scenario?.meta.date" variant="tonal" type="info" density="compact" class="mb-4">日期按场景模板平移，不代表该日真实记录。</VAlert>
<section class="journey-section"><h3>计划与实际</h3><dl class="data-grid"><div v-for="[label,value] in sections[2].fields" :key="label"><dt>{{label}}</dt><dd>{{value??'—'}}</dd></div></dl></section>
<section class="journey-section"><h3>时序节点</h3><p class="caption muted mb-3">未发生节点仅保留计划信息。</p><p v-if="!groups.length" class="muted">暂无时序节点记录</p><div v-for="group in groups" :key="group.category" class="node-group"><h4>{{group.category}}</h4><article v-for="event in group.events" :key="event.id||event.nodeCode" class="journey-node"><strong>{{event.nodeName}} <small>{{event.nodeCode}}</small></strong><div v-if="event.location">位置 <span>{{event.location.roomCode}} · {{event.location.roomName}}</span></div><div>计划 <span>{{time(event.plannedTime)}}</span></div><div>实际 <span>{{event.actualTime?time(event.actualTime):'未发生'}}</span></div><div v-if="event.actualTime" :class="event.deviation>15?'text-error':event.deviation>5?'text-warning':'muted'">{{deviation(event.deviation)}} · {{event.status||'—'}}</div><details v-if="event.operator||event.notes"><summary>操作人与备注</summary><p>{{event.operator||'—'}} · {{event.notes||'无备注'}}</p></details></article></div></section>
<VExpansionPanels variant="accordion" multiple class="journey-metadata"><VExpansionPanel v-for="section in [sections[0],sections[1],sections[3]]" :key="section.title" :title="section.title"><VExpansionPanelText><dl class="data-grid"><div v-for="[label,value] in section.fields" :key="label"><dt>{{label}}</dt><dd>{{value??'—'}}</dd></div></dl></VExpansionPanelText></VExpansionPanel><VExpansionPanel v-if="surgery.vitalSigns?.length" :title="'生命体征采样（'+surgery.vitalSigns.length+' 条）'"><VExpansionPanelText><pre class="vital-records">{{JSON.stringify(surgery.vitalSigns,null,2)}}</pre></VExpansionPanelText></VExpansionPanel></VExpansionPanels><p class="caption muted mt-4">模拟数据 · 只读复盘</p></div></aside></template>
<style scoped>.journey-panel{min-width:0;height:100%;display:flex;flex-direction:column;border-inline-start:1px solid rgba(var(--v-border-color),var(--v-border-opacity));background:rgb(var(--v-theme-surface))}.panel-heading{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:12px;border-bottom:1px solid rgba(var(--v-border-color),var(--v-border-opacity));flex-shrink:0}.panel-heading h2{font-size:16px;font-weight:600;line-height:24px}.journey-content{min-height:0;flex:1;overflow:auto;padding:16px 12px}.selection-summary{display:flex;flex-direction:column;gap:6px;padding-bottom:16px;margin-bottom:20px;border-bottom:1px solid rgba(var(--v-border-color),var(--v-border-opacity));font-size:14px;line-height:22px}.selection-summary strong{font-size:16px;font-weight:600}.journey-section{margin-bottom:24px}.journey-section h3{font-size:14px;font-weight:600;margin-bottom:12px}.journey-section .data-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.data-grid dd{overflow-wrap:anywhere;white-space:normal;font-size:12px;line-height:20px}.data-grid dt{font-size:12px;line-height:20px}.node-group{border-inline-start:2px solid rgba(var(--v-theme-primary),.35);padding-inline-start:12px;margin-bottom:20px}.node-group h4{font-size:14px;font-weight:600;margin-bottom:12px}.journey-node{font-size:12px;line-height:20px;border-bottom:1px solid rgba(var(--v-border-color),var(--v-border-opacity));padding-bottom:12px;margin-bottom:12px}.journey-node:last-child{border:0;margin-bottom:0;padding-bottom:0}.journey-node strong{font-size:14px;font-weight:500;display:block;margin-bottom:6px}.journey-node small{font-size:12px;color:rgba(var(--v-theme-on-surface),.55);margin-inline-start:4px}.journey-node>div{display:flex;gap:8px;flex-wrap:wrap}.journey-node>div>span{margin-inline-start:auto;font-variant-numeric:tabular-nums}.journey-node details{margin-top:6px;color:rgba(var(--v-theme-on-surface),.6)}.journey-metadata .data-grid{grid-template-columns:1fr;gap:12px}.journey-metadata :deep(.v-expansion-panel-text__wrapper){padding:12px}.vital-records{max-height:320px;overflow:auto;font-size:12px;line-height:20px;white-space:pre-wrap;overflow-wrap:anywhere}.journey-placeholder{flex:1;padding:24px 18px;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;gap:16px}.journey-placeholder h3{font-size:16px;font-weight:500}.journey-placeholder p{font-size:14px;line-height:22px;color:rgba(var(--v-theme-on-surface),.6)}</style>
